package com.portfolio.controller;
import com.portfolio.model.Service; import com.portfolio.repository.ServiceRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/services") public class ServiceController { private final ServiceRepository repo; public ServiceController(ServiceRepository r){repo=r;} @GetMapping public List<Service> all(){return repo.findAllByOrderByDisplayOrderAsc();} @GetMapping("/{id}") public ResponseEntity<Service> one(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());} @PostMapping public Service create(@RequestBody Service x){return repo.save(x);} @PutMapping("/{id}") public ResponseEntity<Service> update(@PathVariable Long id,@RequestBody Service p){return repo.findById(id).map(x->{
x.setTitle(p.getTitle());x.setDescription(p.getDescription());x.setIcon(p.getIcon());x.setDisplayOrder(p.getDisplayOrder());return ResponseEntity.ok(repo.save(x));}).orElse(ResponseEntity.notFound().build());} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))return ResponseEntity.notFound().build();repo.deleteById(id);return ResponseEntity.noContent().build();} }